module div8(input [7:0] a, input [7:0] b, output [7:0] q, output [7:0] r);
  reg [7:0] rem; reg [8:0] t; reg [7:0] qq; integer i;
  always @* begin
    rem = 8'd0; qq = 8'd0;
    for (i = 7; i >= 0; i = i - 1) begin
      t = {rem, a[i]};
      if (t >= {1'b0, b}) begin t = t - {1'b0, b}; qq[i] = 1'b1; end
      rem = t[7:0];
    end
  end
  assign q = qq; assign r = rem;
endmodule

module div8(input [7:0] a, input [7:0] b, output [7:0] q, output [7:0] r);
  reg [7:0] rem; reg [8:0] d; reg [7:0] qq; integer i;
  always @* begin
    rem = 8'd0; qq = 8'd0;
    for (i = 7; i >= 0; i = i - 1) begin
      d = {1'b0, rem[6:0], a[i]} - {1'b0, b};
      // rem[7] is nonzero only if the shifted value exceeds 8 bits
      if (rem[7] | ~d[8]) begin
        qq[i] = 1'b1;
        rem = d[7:0];
      end else rem = {rem[6:0], a[i]};
    end
  end
  assign q = qq; assign r = rem;
endmodule
